import java.util.*;
import java.io.*;

public class CF552CVariant5 {
    static BufferedReader br;
    static StringTokenizer st;
    static int w, k;
    static HashSet<Long> set;

    static String next() throws Exception {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return st.nextToken();
    }

    public static void main(String[] args) throws Exception {
        br = new BufferedReader(new InputStreamReader(System.in));
        w = Integer.parseInt(next());
        long n = Long.parseLong(next());

        k = 0;
        for (int i = 0; w > 2 && i < 21; i++) {
            k = i;
            if (Math.pow(w, i) > 1e9) {
                break;
            }
        }

        set = new HashSet<>();
        if (w > 2) {
            long[] pows = new long[k + 1];
            for (int i = 0; i <= k; i++) {
                pows[i] = (long) Math.pow(w, i);
            }
            solve(0, 0, pows);
        }

        boolean bol = (w == 2);
        for (long i : set) {
            if (i >= n && set.contains(i - n)) {
                bol = true;
                break;
            }
        }

        PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));
        pw.println(bol ? "YES" : "NO");
        pw.close();
    }

    static void solve(int i, long sum, long[] pows) {
        if (i > k) {
            set.add(sum);
            return;
        }
        solve(i + 1, sum + pows[i], pows);
        solve(i + 1, sum, pows);
    }
}
